-- 4. Updated At Trigger Function & Trigger
CREATE OR REPLACE FUNCTION public.handle_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = timezone('utc'::text, now());
  RETURN NEW;
END;
$$ LANGUAGE plpgsql

-- 5. Helper Functions for Secure RLS (SECURITY DEFINER avoids recursion)
CREATE OR REPLACE FUNCTION public.get_current_user_role()
RETURNS public.user_role AS $$
DECLARE
  v_role public.user_role;
BEGIN
  SELECT role INTO v_role
  FROM public.profiles
  WHERE id = auth.uid() AND is_active = true;

  RETURN v_role;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public

CREATE EXTENSION IF NOT EXISTS pgcrypto;
ALTER TABLE public.watch_sessions ADD COLUMN IF NOT EXISTS session_token TEXT;
UPDATE public.watch_sessions SET session_token = encode(extensions.gen_random_bytes(32), 'hex') WHERE session_token IS NULL;
ALTER TABLE public.watch_sessions ALTER COLUMN session_token SET NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_watch_sessions_session_token ON public.watch_sessions(session_token);
COMMENT ON COLUMN public.watch_sessions.session_token IS 'Private per-session capability required for anonymous tracking writes; never exposed in analytics responses.';

