CREATE OR REPLACE FUNCTION public.accept_invitation(
  p_invitation_id UUID,
  p_token_hash TEXT,
  p_email TEXT,
  p_clickup_user_id TEXT,
  p_name TEXT
)
RETURNS public.profiles
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_invitation public.invitations;
  v_profile public.profiles;
  v_email TEXT := lower(trim(p_email));
  v_now TIMESTAMPTZ := timezone('utc'::text, now());
BEGIN
  IF p_invitation_id IS NULL OR p_token_hash IS NULL OR p_clickup_user_id IS NULL OR v_email = '' THEN
    RAISE EXCEPTION 'invalid_invitation';
  END IF;

  SELECT * INTO v_invitation
  FROM public.invitations
  WHERE id = p_invitation_id
    AND token_hash = p_token_hash
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'invalid_invitation'; END IF;
  IF v_invitation.accepted_at IS NOT NULL THEN RAISE EXCEPTION 'invitation_accepted'; END IF;
  IF v_invitation.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'invitation_revoked'; END IF;
  IF v_invitation.expires_at <= v_now THEN RAISE EXCEPTION 'invitation_expired'; END IF;
  IF v_invitation.email <> v_email THEN RAISE EXCEPTION 'invitation_email_mismatch'; END IF;
  IF v_invitation.role NOT IN ('admin'::public.user_role, 'viewer'::public.user_role) THEN RAISE EXCEPTION 'invalid_invitation'; END IF;

  SELECT * INTO v_profile FROM public.profiles WHERE id = v_invitation.profile_id FOR UPDATE;
  IF NOT FOUND OR v_profile.email <> v_email THEN RAISE EXCEPTION 'invitation_email_mismatch'; END IF;
  IF v_profile.clickup_user_id IS NOT NULL AND v_profile.clickup_user_id <> p_clickup_user_id THEN RAISE EXCEPTION 'profile_identity_mismatch'; END IF;

  UPDATE public.profiles
  SET clickup_user_id = p_clickup_user_id, name = COALESCE(NULLIF(trim(p_name), ''), name), role = v_invitation.role, is_active = true
  WHERE id = v_profile.id
  RETURNING * INTO v_profile;

  UPDATE public.invitations SET accepted_at = v_now WHERE id = v_invitation.id AND accepted_at IS NULL AND revoked_at IS NULL;
  RETURN v_profile;
END;
$$;
REVOKE ALL ON FUNCTION public.accept_invitation(UUID, TEXT, TEXT, TEXT, TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.accept_invitation(UUID, TEXT, TEXT, TEXT, TEXT) FROM anon;
REVOKE ALL ON FUNCTION public.accept_invitation(UUID, TEXT, TEXT, TEXT, TEXT) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.accept_invitation(UUID, TEXT, TEXT, TEXT, TEXT) TO service_role;

CREATE OR REPLACE FUNCTION public.touch_profile_last_seen(p_profile_id UUID)
RETURNS TIMESTAMPTZ
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_now TIMESTAMPTZ := timezone('utc'::text, now());
  v_last_seen TIMESTAMPTZ;
BEGIN
  UPDATE public.profiles
  SET last_seen_at = v_now
  WHERE id = p_profile_id
    AND (last_seen_at IS NULL OR last_seen_at <= v_now - interval '5 minutes')
  RETURNING last_seen_at INTO v_last_seen;
  IF v_last_seen IS NULL THEN
    SELECT last_seen_at INTO v_last_seen FROM public.profiles WHERE id = p_profile_id;
  END IF;
  RETURN v_last_seen;
END;
$$;
REVOKE ALL ON FUNCTION public.touch_profile_last_seen(UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.touch_profile_last_seen(UUID) FROM anon;
REVOKE ALL ON FUNCTION public.touch_profile_last_seen(UUID) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.touch_profile_last_seen(UUID) TO service_role;

-- TrackUp Analytics: bind new watch sessions to profiles and preserve ordered telemetry.
-- Existing rows remain valid; legacy sessions/events without these fields stay explicitly anonymous.

ALTER TYPE public.watch_event_type ADD VALUE IF NOT EXISTS 'buffer';
ALTER TYPE public.watch_event_type ADD VALUE IF NOT EXISTS 'rate_change';
ALTER TYPE public.watch_event_type ADD VALUE IF NOT EXISTS 'visibility_change';

ALTER TABLE public.watch_sessions
  ADD COLUMN IF NOT EXISTS viewer_profile_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS device_type TEXT,
  ADD COLUMN IF NOT EXISTS browser TEXT,
  ADD COLUMN IF NOT EXISTS os TEXT;

CREATE INDEX IF NOT EXISTS idx_watch_sessions_viewer_profile_id
  ON public.watch_sessions(viewer_profile_id);
CREATE INDEX IF NOT EXISTS idx_watch_sessions_viewer_profile_started_at
  ON public.watch_sessions(viewer_profile_id, started_at DESC);

ALTER TABLE public.watch_events
  ADD COLUMN IF NOT EXISTS client_event_id TEXT,
  ADD COLUMN IF NOT EXISTS sequence_number INTEGER,
  ADD COLUMN IF NOT EXISTS occurred_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS metadata JSONB NOT NULL DEFAULT '{}'::jsonb;

CREATE UNIQUE INDEX IF NOT EXISTS uq_watch_events_session_client_event
  ON public.watch_events(session_id, client_event_id);
CREATE INDEX IF NOT EXISTS idx_watch_events_session_sequence
  ON public.watch_events(session_id, sequence_number);
CREATE INDEX IF NOT EXISTS idx_watch_events_session_occurred_at
  ON public.watch_events(session_id, occurred_at);

COMMENT ON COLUMN public.watch_sessions.viewer_profile_id IS
  'Authenticated TrackUp profile associated with this watch session; legacy hashed-only sessions remain NULL.';
COMMENT ON COLUMN public.watch_sessions.device_type IS
  'Coarse device class derived server-side from the request user-agent; NULL when unknown.';
COMMENT ON COLUMN public.watch_sessions.browser IS
  'Browser family derived server-side from the request user-agent; NULL when unknown.';
COMMENT ON COLUMN public.watch_sessions.os IS
  'Operating-system family derived server-side from the request user-agent; NULL when unknown.';
COMMENT ON COLUMN public.watch_events.client_event_id IS
  'Client-generated idempotency key for one playback event; never contains PII.';
COMMENT ON COLUMN public.watch_events.sequence_number IS
  'Monotonic per-session client sequence used to reconstruct playback order.';
COMMENT ON COLUMN public.watch_events.occurred_at IS
  'Client playback timestamp; created_at remains the server receipt timestamp.';
COMMENT ON COLUMN public.watch_events.metadata IS
  'Non-PII provider event metadata such as visibility or playback rate.';

CREATE TABLE IF NOT EXISTS public.viewer_identities (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  watch_link_id UUID NOT NULL REFERENCES public.watch_links(id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (char_length(trim(name)) BETWEEN 1 AND 120),
  email TEXT NOT NULL CHECK (char_length(email) BETWEEN 3 AND 320),
  normalized_email TEXT NOT NULL CHECK (char_length(normalized_email) BETWEEN 3 AND 320),
  created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc', now()),
  last_seen_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc', now()),
  UNIQUE (watch_link_id, normalized_email)
);

CREATE INDEX IF NOT EXISTS idx_viewer_identities_watch_link_id ON public.viewer_identities(watch_link_id);
