CREATE INDEX IF NOT EXISTS idx_watch_sessions_viewer_identity_id ON public.watch_sessions(viewer_identity_id);
COMMENT ON TABLE public.viewer_identities IS 'Validated guest viewer identity scoped to a private watch link; read/write only through server-side service role.';
COMMENT ON COLUMN public.viewer_identities.normalized_email IS 'Lowercase trimmed email used only for deduplication within one watch link.';
COMMENT ON COLUMN public.watch_sessions.viewer_identity_id IS 'Guest viewer identity for private-link viewers; mutually exclusive in normal operation with viewer_profile_id.';

CREATE TABLE IF NOT EXISTS public.owner_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
  level TEXT NOT NULL CHECK (level IN ('INFO', 'WARN', 'ERROR')),
